import type { Metadata } from "next";
import { siteConfig } from "@/data/site";
import { founderData } from "@/data/team";
import { serviceCategories } from "@/data/services";

/** Public URL of the founder's profile page (also the Person entity's home). */
export const FOUNDER_PATH = "/easin-arafat";

export const ids = {
  organization: `${siteConfig.url}/#organization`,
  website: `${siteConfig.url}/#website`,
  founder: `${siteConfig.url}${FOUNDER_PATH}#person`
};

/** Default share image (generated by app/opengraph-image.tsx). */
const defaultShareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} — Websites, SaaS, AI automation, SEO & GEO in Dhaka`
};

/**
 * Per-page metadata: title, description, a canonical URL and matching
 * Open Graph / Twitter fields. A page's openGraph replaces the layout's
 * (shallow merge), so the share image is set here on every page.
 */
export function pageMetadata({
  title,
  description,
  path,
  type = "website",
  absoluteTitle = false,
  image = defaultShareImage
}: {
  title: string;
  description: string;
  path: string;
  type?: "website" | "article" | "profile";
  /** Use the title as-is, without the " | ScaleUp Web" suffix. */
  absoluteTitle?: boolean;
  image?: { url: string; width: number; height: number; alt: string };
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      url: path,
      title: fullTitle,
      description,
      siteName: siteConfig.name,
      locale: "en_US",
      images: [image]
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [image] }
  };
}

/** Escapes "<" so JSON-LD can't break out of its <script> tag. */
export function toJsonLd(data: unknown) {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}

/** The founder as a schema.org Person — used site-wide and on the founder page. */
export function founderPerson() {
  return {
    "@type": "Person",
    "@id": ids.founder,
    name: founderData.name,
    url: `${siteConfig.url}${FOUNDER_PATH}`,
    image: `${siteConfig.url}${founderData.photo}`,
    jobTitle: founderData.role,
    description: `${founderData.name} is a web developer in Dhaka, Bangladesh, and the founder of ${siteConfig.name}.`,
    worksFor: { "@id": ids.organization },
    address: { "@type": "PostalAddress", addressLocality: siteConfig.address.city, addressCountry: "BD" },
    knowsAbout: [
      "Web development",
      "Next.js",
      "SaaS development",
      "E-commerce development",
      "AI automation",
      "Search engine optimization",
      "Generative engine optimization"
    ],
    sameAs: [founderData.linkedin]
  };
}

/** Organization + WebSite + founder graph, rendered once in the root layout. */
export function siteGraph() {
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "ProfessionalService",
        "@id": ids.organization,
        name: siteConfig.name,
        url: siteConfig.url,
        logo: `${siteConfig.url}/icon.png`,
        image: `${siteConfig.url}/opengraph-image`,
        description: siteConfig.description,
        email: siteConfig.contactEmail,
        telephone: siteConfig.phone,
        founder: { "@id": ids.founder },
        address: {
          "@type": "PostalAddress",
          streetAddress: siteConfig.address.street,
          addressLocality: siteConfig.address.city,
          postalCode: siteConfig.address.postalCode,
          addressCountry: "BD"
        },
        geo: { "@type": "GeoCoordinates", latitude: 23.7602, longitude: 90.3923 },
        areaServed: ["Bangladesh", "Worldwide"],
        openingHoursSpecification: {
          "@type": "OpeningHoursSpecification",
          dayOfWeek: ["Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday"],
          opens: "10:00",
          closes: "22:00"
        },
        knowsAbout: serviceCategories.map((c) => c.title),
        hasOfferCatalog: {
          "@type": "OfferCatalog",
          name: "Services",
          itemListElement: serviceCategories.flatMap((c) =>
            c.services.map((s) => ({
              "@type": "Offer",
              itemOffered: {
                "@type": "Service",
                name: s.title,
                url: `${siteConfig.url}/services/${c.slug}/${s.slug}`
              }
            }))
          )
        }
      },
      {
        "@type": "WebSite",
        "@id": ids.website,
        url: siteConfig.url,
        name: siteConfig.name,
        publisher: { "@id": ids.organization },
        inLanguage: "en"
      },
      founderPerson()
    ]
  };
}

/** BreadcrumbList from [label, path] pairs (Home is added automatically). */
export function breadcrumbs(items: [string, string][]) {
  const all: [string, string][] = [["Home", "/"], ...items];
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: all.map(([name, path], i) => ({
      "@type": "ListItem",
      position: i + 1,
      name,
      item: `${siteConfig.url}${path === "/" ? "" : path}`
    }))
  };
}
